values ('dialog_merchant_greet', NULL, 'npc_general_merchant', 'greet', '[{"id": "greet", "text": "Welcome traveler. Supplies, tools, or something rare?", "options": [{"text": "Show me your wares.", "next": "shop", "action": "open_shop"}, {"text": "Any rumors around here?", "next": "rumor"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "rumor", "text": "Word is the Cradle Expanse has been unstable lately. Aethel storms are getting worse.", "options": [{"text": "Interesting.", "next": "greet"}, {"text": "Thanks.", "next": "exit", "action": "exit"}]}, {"id": "shop", "text": "Take a look.", "options": []}]'::jsonb, 'dialog_tree_master.json', 0)
