values ('dialog_innkeeper_greet', NULL, 'npc_innkeeper', 'greet', '[{"id": "greet", "text": "You look exhausted. A room will restore your strength.", "options": [{"text": "Rest for the night.", "next": "rest", "action": "rest_inn"}, {"text": "Just passing through.", "next": "exit", "action": "exit"}]}, {"id": "rest", "text": "Your wounds fade as you rest.", "options": []}]'::jsonb, 'dialog_tree_master.json', 2)
