values ('dialog_valen_main', NULL, 'npc_concordium_officer', 'greet', '[{"id": "greet", "text": "Citizen, security around Nexus has tightened. We could use capable fighters.", "options": [{"text": "I''m ready to help.", "next": "quest", "action": "accept_quest"}, {"text": "Any updates?", "next": "info"}, {"text": "Not now.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_valen_security", "action": ""}]}, {"id": "info", "text": "Strange creatures have been appearing near the Cradle perimeter.", "options": [{"text": "I''ll handle it.", "next": "quest", "action": "accept_quest"}, {"text": "I''ll return later.", "next": "exit", "action": "exit"}]}, {"id": "amb_valen_security", "text": "The report is filed. The names are filed separately. I don''t want anyone becoming a number because the cabinet ran out of space.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 4)
