insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_concordium', NULL, 'npc_concordium_class_trainer', 'greet', '[{"id": "greet", "text": "Discipline and unity define the Concordium. What training do you seek?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "I want a mission to prove my worth.", "next": "take_quest"}, {"text": "Tell me about Concordium combat doctrine.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Concordium fighters are trained to endure and protect. A disciplined soldier can hold the line against any storm.", "options": [{"text": "Understood.", "next": "greet"}, {"text": "That is all.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Choose your combat specialization carefully, soldier. The Concordium demands commitment — once you walk a path, there is no turning back.", "options": [{"text": "Show me the available specializations.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Focus and refine your abilities.", "options": []}, {"id": "take_quest", "text": "The Concordium does not hand out ranks freely. If you seek to advance your specialization, you must first complete a field assignment. Patrol the designated sector, eliminate hostile targets, and return with proof of your discipline. Only then will we consider your promotion.", "options": [{"text": "I''ll prepare first.", "next": "greet"}, {"text": "I''m ready. Assign me the mission.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 13)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_arcanum', NULL, 'npc_arcanum_class_trainer', 'greet', '[{"id": "greet", "text": "Knowledge is power, but power must be wielded correctly. What arcane discipline do you wish to master?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Is there a trial I can undertake?", "next": "take_quest"}, {"text": "Tell me about Arcanum combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We Seekers unravel the mysteries of the Prima Materia. Our combat relies on unlocking the universe''s hidden truths and bending them to our will.", "options": [{"text": "Fascinating.", "next": "greet"}, {"text": "I must go.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Peer into the void and choose your path. The arcane arts demand absolute dedication — once chosen, your path is sealed by the Prima Materia itself.", "options": [{"text": "Let me study the available paths.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let us refine your mastery over the arcane.", "options": []}, {"id": "take_quest", "text": "Advancement among the Seekers is not given — it is discovered. There is an anomaly in the field that requires investigation. Collect samples, neutralize any corrupted entities you encounter, and document your findings. Your performance will determine whether you are worthy of deeper knowledge.", "options": [{"text": "I need more time to prepare.", "next": "greet"}, {"text": "I accept the trial.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 14)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_hegemony', NULL, 'npc_hegemony_class_trainer', 'greet', '[{"id": "greet", "text": "Only the strong survive the scrap yards! Are you here to forge yourself into a weapon?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Give me a fight to prove myself.", "next": "take_quest"}, {"text": "Tell me about Hegemony tactics.", "next": "lore"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We don''t rely on shiny tech or fancy magic. Pure, unadulterated physical superiority and raw firepower rule the Iron Hegemony.", "options": [{"text": "Understood, Marshal.", "next": "greet"}, {"text": "I have to leave.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Pick your weapon, pick your war. Once you commit, there''s no going soft. The Hegemony doesn''t tolerate indecision.", "options": [{"text": "Show me what I can become.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let''s beat some combat sense into you.", "options": []}, {"id": "take_quest", "text": "You want a new class? Then earn it with blood and sweat. There''s a pack of hostiles causing trouble in our territory. Go out there, crush every last one of them, and drag yourself back here alive. Do that, and I''ll consider you worthy of advancement.", "options": [{"text": "Not yet, Marshal.", "next": "greet"}, {"text": "Point me to the fight.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 15)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_custodians', NULL, 'npc_custodian_class_trainer', 'greet', '[{"id": "greet", "text": "The Custodians protect the balance of Xylos. How may I assist your training?", "options": [{"text": "Change my class specialization.", "next": "class", "action": "open_class_change"}, {"text": "Improve my combat techniques.", "next": "skills", "action": "open_skill_training"}, {"text": "I wish to undertake an advancement trial.", "next": "take_quest"}, {"text": "Tell me about the Custodians.", "next": "lore"}, {"text": "I''ll return later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Galactic Custodians exist to preserve order across Xylos and prevent total war between factions.", "options": [{"text": "I understand.", "next": "greet"}, {"text": "Thank you.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Your specialization will define your role in maintaining the balance. Choose wisely — this decision is permanent and irreversible.", "options": [{"text": "Show me the available roles.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Focus. Precision leads to victory.", "options": []}, {"id": "take_quest", "text": "The Custodians require balanced judgment, not just raw power. We have received reports of instability in a nearby zone. Investigate the disturbance, neutralize any threats to civilian safety, and file a complete report. Your conduct during this mission will determine your eligibility for specialization advancement.", "options": [{"text": "I will return when I am prepared.", "next": "greet"}, {"text": "I accept the assignment.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 16)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_mercenary', NULL, 'npc_mercenary_class_trainer', 'greet', '[{"id": "greet", "text": "Heh. Another rookie looking to survive out here?", "options": [{"text": "Change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train some combat skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Got any jobs that''ll get me promoted?", "next": "take_quest"}, {"text": "Any advice for surviving Xylos?", "next": "lore"}, {"text": "I''m good.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Rule one kid — never trust a quiet battlefield. Rule two — always keep your weapon ready.", "options": [{"text": "Good advice.", "next": "greet"}, {"text": "I''ll remember that.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Listen up, kid. You pick a fighting style and you stick with it. No refunds, no do-overs. That''s how it works out here.", "options": [{"text": "Alright, show me what''s on the table.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Alright, let''s sharpen those skills.", "options": []}, {"id": "take_quest", "text": "Heh, eager one. Alright, I''ve got a contract that nobody else wants to touch — too dangerous, too dirty. Clear out the target zone, grab whatever intel you can find, and make it back in one piece. Pull that off and I''ll bump you up. Fail, and... well, don''t fail.", "options": [{"text": "Let me think about it.", "next": "greet"}, {"text": "Hand me the contract.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 17)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_meridian', NULL, 'npc_meridian_class_trainer', 'greet', '[{"id": "greet", "text": "Time is credits, friend. You looking to learn how to fight dirty and get paid, or what?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Any high-paying jobs that come with a promotion?", "next": "take_quest"}, {"text": "Tell me about Cartel combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Fair fights are for fools who end up dead and broke. We hit fast, hit where it hurts, and make sure we walk away with the prize.", "options": [{"text": "Makes sense.", "next": "greet"}, {"text": "I''m out.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Every specialist has a niche. Pick yours and own it — the Cartel doesn''t pay for second chances. Choose once, profit forever.", "options": [{"text": "Let me see the specializations.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let''s sharpen those tricks up.", "options": []}, {"id": "take_quest", "text": "Advancement in the Cartel means proving you can deliver results. There''s a shipment route that''s been compromised — hostiles are raiding our supply lines. Eliminate the threat, secure the cargo, and bring back proof. Do this cleanly and your specialization upgrade is guaranteed. Mess it up and you owe me for the lost merchandise.", "options": [{"text": "I''ll pass for now.", "next": "greet"}, {"text": "Consider it done.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 18)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_omnicorp', NULL, 'npc_omnicorp_class_trainer', 'greet', '[{"id": "greet", "text": "Welcome to OmniCorp Combat Systems. Would you like to optimize your combat designation today?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Are there field tests available for advancement?", "next": "take_quest"}, {"text": "Tell me about OmniCorp warfare.", "next": "lore"}, {"text": "No, thank you.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Efficiency above all. Through cybernetic enhancements and predictive AI targeting, our operatives achieve a 98.7% success rate.", "options": [{"text": "Impressive stats.", "next": "greet"}, {"text": "Terminating conversation.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "WARNING: Combat system reconfiguration is a one-time procedure. Once installed, your combat protocol cannot be reverted. Proceed with caution.", "options": [{"text": "Display available combat systems.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Initiating skill calibration protocol...", "options": []}, {"id": "take_quest", "text": "NOTICE: Class advancement requires completion of a certified field evaluation. Proceed to the designated combat zone, eliminate all marked targets within operational parameters, and return sensor data for analysis. Performance metrics will be reviewed by OmniCorp Tactical Division. Minimum efficiency threshold: 85%.", "options": [{"text": "Postpone evaluation.", "next": "greet"}, {"text": "Initiate field test.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 19)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_shard', NULL, 'npc_shard_class_trainer', 'greet', '[{"id": "greet", "text": "The Aethel whispers, child. Are you ready to embrace its holy light and purge the non-believers?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "How can I prove my devotion for advancement?", "next": "take_quest"}, {"text": "Tell me about Shard doctrine.", "next": "lore"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Technology is a cancer. We draw our strength directly from the divine fragments of the Aethel Shard, striking with zealous fury.", "options": [{"text": "I see the truth.", "next": "greet"}, {"text": "I must pray.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "The Aethel reveals your true calling, child. But once chosen, your soul is bound to that path. The Shard does not grant second chances.", "options": [{"text": "Show me the sacred paths.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let the light empower your strikes.", "options": []}, {"id": "take_quest", "text": "The Aethel tests all who seek its deeper gifts. A corruption festers in the wilds — an affront to the Shard''s sacred energy. Purge the tainted creatures, cleanse the desecrated ground, and offer the remains to the Shard. Return purified, and the Aethel will open a new path for your soul.", "options": [{"text": "I must meditate on this.", "next": "greet"}, {"text": "I will carry out the purification.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 20)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_legion', NULL, 'npc_legion_class_trainer', 'greet', '[{"id": "greet", "text": "Honor and blood, warrior! Do you seek to prove your worth to the Starforged Legion?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Is there a trial of honor I can undertake?", "next": "take_quest"}, {"text": "Tell me about Legion combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A home is earned by strength of arms. We fight with disciplined formations, unbreakable shields, and the memory of our lost world.", "options": [{"text": "For the Legion.", "next": "greet"}, {"text": "Farewell.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "A warrior chooses their blade once and carries it to the grave. No excuses, no regrets. Declare your role, soldier — this is permanent.", "options": [{"text": "Show me the battlefield roles.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let us hone your combat prowess.", "options": []}, {"id": "take_quest", "text": "Every rank in the Legion is forged in battle. There is a warzone that needs a soldier with guts. March into hostile territory, hold the line against incoming waves, and eliminate the commanding officer. Return with their insignia as proof. Do this with honor, and your advancement is earned — not given.", "options": [{"text": "I need to gear up first.", "next": "greet"}, {"text": "For the Legion. I march now.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 21)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_master', NULL, 'npc_class_architect', 'greet', '[{"id": "greet", "text": "Every warrior begins somewhere. I can guide you to your true path.", "options": [{"text": "Change my class.", "next": "class_menu", "action": "open_class_change"}, {"text": "Tell me about classes.", "next": "explain"}, {"text": "Not now.", "next": "exit", "action": "exit"}]}, {"id": "explain", "text": "Each class represents a different combat philosophy. Choose wisely, for it will shape your journey across Xylos.", "options": [{"text": "Let me choose.", "next": "class_menu", "action": "open_class_change"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "class_menu", "text": "Focus your will. Your path awaits.", "options": []}]'::jsonb, 'dialog_tree_master.json', 22)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_advisor', NULL, 'npc_class_advisor', 'intro', '[{"id": "intro", "text": "Welcome to Xylos, traveler. Before you begin your journey, you must choose a combat class.", "options": [{"text": "Where can I choose a class?", "next": "locations"}, {"text": "Tell me what a class is.", "next": "explain"}, {"text": "I''ll explore on my own.", "next": "exit", "action": "exit"}]}, {"id": "explain", "text": "A class defines how you fight and the abilities you will learn. Trainers across the capitals of Xylos can guide you in choosing your path.", "options": [{"text": "Where can I find these trainers?", "next": "locations"}, {"text": "Understood.", "next": "exit", "action": "exit"}]}, {"id": "locations", "text": "Class Trainers can be found in the major capitals of Xylos. Visit one of them to begin your training.", "options": [{"text": "Thanks for the guidance.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_tree_master.json', 23)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_concordium_ama_main', NULL, 'NPC_CONCORDIUM_EXCHANGE', 'greet', '[{"id": "greet", "text": "AMA Branch Office — Concordium. I can facilitate exchanges between your faction currency (AMC) and the universal Credent (CRD). Current rates fluctuate based on twelve economic factors. State your intent.", "options": [{"text": "I want to exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "How do exchange rates work?", "next": "explain_rates"}, {"text": "Nothing for now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "Exchange rates are computed dynamically by the AMA. Factors include territory control, treasury health, inflation, trade volume, and more. A sliding fee of 1–5% applies per transaction based on volume. The rate is always live — it reflects the current state of the economy.", "options": [{"text": "I want to exchange now.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I''ll come back later.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Processing your exchange request. The AMA Ledger records all transactions.", "options": []}]'::jsonb, 'dialog_tree_master.json', 24)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_arcanum_ama_main', NULL, 'NPC_ARCANUM_EXCHANGE', 'greet', '[{"id": "greet", "text": "Fascinating to have a client! I handle QNT-to-CRD and CRD-to-QNT exchanges here. The volatility of Arcanum currency is actually a mathematical marvel — it responds to knowledge sector output and energy research cycles. But I digress. How can I assist?", "options": [{"text": "I want to exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me more about the rates.", "next": "explain_rates"}, {"text": "I''ll think about it.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "QNT value is heavily influenced by Arcanum''s research output and territorial control. When the Seekers control high-value knowledge sites, QNT strengthens considerably. Fee is 1–5% sliding scale by volume. I''ve written four papers on this if you''d like—", "options": [{"text": "Just the exchange, please.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Splendid! Initiating exchange protocol. The AMA Ledger awaits your input.", "options": []}]'::jsonb, 'dialog_tree_master.json', 25)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_iron_ama_main', NULL, 'NPC_IRON_EXCHANGE', 'greet', '[{"id": "greet", "text": "TERMINAL IH-3 ACTIVE. SERVICES: IGT-CRD EXCHANGE. CURRENT RATE: LIVE. FEE: 1-5%. SELECT OPTION.", "options": [{"text": "Begin exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Display rate information.", "next": "explain_rates"}, {"text": "Abort.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "IGT RATE FACTORS: MILITARY OUTPUT, INDUSTRIAL PRODUCTION, TERRITORY, TREASURY HEALTH, TWELVE VARIABLES TOTAL. RATE RANGE: 0.25-3.00 CRD PER IGT. FEE DEDUCTED FROM OUTPUT. NO FURTHER INFORMATION AVAILABLE.", "options": [{"text": "Begin exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Abort.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "TRANSACTION INITIATED. AWAITING INPUT.", "options": []}]'::jsonb, 'dialog_tree_master.json', 26)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_meridian_ama_main', NULL, 'NPC_MERIDIAN_EXCHANGE', 'greet', '[{"id": "greet", "text": "Welcome to the busiest AMA desk in Xylos! We handle AUC-to-CRD and back with the smoothest process you''ll find anywhere. Between us — when trade volume is high here, you might find the rates particularly favourable. Shall we?", "options": [{"text": "Let''s exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me about the rates.", "next": "explain_rates"}, {"text": "Not right now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "AUC is tied to trade dominance. The Cartel''s grip on commerce directly strengthens the Aurum Cipher. High-volume transactions attract a lower fee — 1% for large trades, 5% for small ones. My advice? Don''t exchange in small increments.", "options": [{"text": "Good tip. Let''s exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I''ll keep that in mind.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Excellent choice. Opening the exchange interface now.", "options": []}]'::jsonb, 'dialog_tree_master.json', 27)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_omnicorp_ama_main', NULL, 'NPC_OMNICORP_EXCHANGE', 'greet', '[{"id": "greet", "text": "OmniCorp AMA Integration Node online. Services available: OMC-to-CRD exchange, CRD-to-OMC exchange. OmniCorp is not responsible for rate fluctuations. The AMA guarantees ledger integrity. Terms and conditions apply. How may I process your transaction?", "options": [{"text": "Open exchange interface.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Rate information.", "next": "explain_rates"}, {"text": "Disconnect.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "OmniCred value is indexed to OmniCorp''s patent portfolio valuation, off-world trade agreements, R&D throughput, and resource export volumes. Rate range: 0.25 to 3.00 CRD per OMC. Fee: 1% to 5% sliding by volume. Processing time: immediate. Disclaimer: past rate performance is not indicative of future results.", "options": [{"text": "Proceed with exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "End session.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Initiating exchange module. CoreNet™ connection secure.", "options": []}]'::jsonb, 'dialog_tree_master.json', 28)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_shard_ama_main', NULL, 'NPC_SHARD_EXCHANGE', 'greet', '[{"id": "greet", "text": "...The Shard breathes. And in its breath, all things flow — including currency. I am Mirya. I can exchange your Aethel-Tithes (ATH) for Credent, or the reverse. The AMA requires I do this. The Shard permits it. What do you seek?", "options": [{"text": "I seek currency exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me about the exchange.", "next": "explain_rates"}, {"text": "I will return another time.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "ATH is sacred in nature, and thus unpredictable by worldly measures. Its value rises when the Shard controls the pulse-points of Xylos, and falls when the sacred sites are held by those without faith. The AMA has learned to accept this. A fee is taken — 1 to 5 of every 100 — as offering to the system.", "options": [{"text": "I am ready to exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I will meditate on it.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "May the exchange be balanced. The interface opens before you.", "options": []}]'::jsonb, 'dialog_tree_master.json', 29)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_legion_ama_main', NULL, 'NPC_LEGION_EXCHANGE', 'greet', '[{"id": "greet", "text": "Rex Valdur, AMA Forward Station. We handle Legion Scrip (LSC) and CRD, both directions. I run a tight operation here — fast processing, fair rates, no nonsense. The Legion appreciates efficiency. So do I. What are we moving?", "options": [{"text": "Exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "What are the current rates?", "next": "explain_rates"}, {"text": "Stand down for now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "LSC tracks Legion military readiness and territorial control. Strong Legion presence in contested zones pushes the Scrip up. Fee is 1–5% depending on volume — high-volume traders get the better deal. I''ve seen this station process 50,000 LSC in a single session. Don''t be shy.", "options": [{"text": "Let''s go.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Not today.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Exchange interface open. Make it count.", "options": []}]'::jsonb, 'dialog_tree_master.json', 30)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_quest_terminal', NULL, 'npc_quest_board', 'greet', '[{"id": "greet", "text": "[TERMINAL ACTIVE] Select contract category to proceed.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "An automated posting terminal that aggregates Concordium-approved contracts and public bounties.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 31)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_hale_main', NULL, 'npc_director_hale', 'greet', '[{"id": "greet", "text": "Every asset is expendable if the mission succeeds. I''ll be direct with you.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_hale_containment", "action": ""}]}, {"id": "local", "text": "Director Hale oversees Concordium containment operations in the Inner Cradle. Cold and calculating, she treats casualties as acceptable variables.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_hale_containment", "text": "A stable perimeter is measurable. Reassurance isn''t. I know which one the review board will fund.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 32)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_vael_main', NULL, 'npc_concordium_overseer', 'greet', '[{"id": "greet", "text": "The readings are off again. Don''t touch anything without filing a request.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_vael_manifest", "action": ""}]}, {"id": "local", "text": "A bureaucrat stationed at the outer boundary, cataloguing anomalous energy readings with obsessive precision.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_vael_manifest", "text": "The manifest says six replacement seals arrived. I have five seals and six signatures. Please don''t ask me which one is wrong before my tea.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 33)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_rian_scout', NULL, 'npc_garden_scout', 'greet', '[{"id": "greet", "text": "Eyes open out here — the mutations near the eastern cluster have been getting aggressive.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_rian_observation", "action": ""}]}, {"id": "local", "text": "A young Concordium scout on rotation through the Gardens, cataloguing flora mutations and monster migration patterns.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_rian_observation", "text": "The slimes are where the old drainage map says water should pool. That''s a pattern. It isn''t proof of what changed them.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 34)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_scavenger', NULL, 'npc_scavenger', 'greet', '[{"id": "greet", "text": "Junk? Treasure? Same thing, different buyer. Let''s talk.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_scavenger_claim", "action": ""}]}, {"id": "local", "text": "Junk-Eye Joe lost one eye to a collapsing ceiling in this very district. He replaced it with a salvaged scope lens and kept digging.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_scavenger_claim", "text": "I tag what I can carry and leave what I can''t. The dangerous part is convincing everyone else that the tag means anything.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 35)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_patrol_guard', NULL, 'npc_patrol_guard', 'greet', '[{"id": "greet", "text": "Another contract? Fine. Just don''t get killed where I can see it.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A seasoned guard captain who has held the eastern perimeter for eleven years. He''s run out of things to be surprised by.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 36)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_veteran_kael', NULL, 'npc_veteran_explorer', 'greet', '[{"id": "greet", "text": "Sit down. This''ll take a minute. Or don''t — your loss.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_world_severance", "action": ""}, {"text": "Any word from around here?", "next": "rumor_great_fracture", "action": ""}]}, {"id": "local", "text": "Old Man Kael claims to have explored every district before the Great Fracture. His stories contradict each other perfectly.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_world_severance", "text": "People call every old crack a Severance scar. Most are just old cracks. The distinction matters when you''re choosing where to build.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_great_fracture", "text": "Old Man Kael calls it the Great Fracture. The archive index uses a different title.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 37)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_elara_scholar', NULL, 'npc_arcanum_scholar', 'greet', '[{"id": "greet", "text": "I''ll spare you the background reading — just tell me what you know.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_arcanum_assistant", "action": ""}]}, {"id": "local", "text": "Scholar Elara specialises in Aethel resonance mapping. She has published seventeen papers. She mentions this within thirty seconds of meeting anyone.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_arcanum_assistant", "text": "Three instruments agree on the pulse timing. They disagree on what the pulse means. Elara says that is a better result than false certainty.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 38)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_sylas_main', NULL, 'npc_arcanum_archivist', 'greet', '[{"id": "greet", "text": "Access is tiered. What clearance do you carry?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_archivist_rumor", "action": ""}, {"text": "Any word from around here?", "next": "rumor_aethelgard_descendants", "action": ""}]}, {"id": "local", "text": "Archivist Sylas guards the Seekers'' historical records with paranoid precision. He can recall exact shelf locations for 40,000 documents.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_archivist_rumor", "text": "Aethelgardian records were copied by hand when the first vaults began to fail. Some errors may be the only surviving witnesses.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_aethelgard_descendants", "text": "Some records suggest descendants remained on Xylos. The margin note is later than the document it annotates.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 39)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_finn_novice', NULL, 'npc_novice_researcher', 'greet', '[{"id": "greet", "text": "Oh! You''re here! I was just about to try something probably-safe!", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "Any word from around here?", "next": "rumor_arcanum_samples", "action": ""}]}, {"id": "local", "text": "Finn is enthusiastic to a fault and has already accidentally detonated two crystal clusters this season.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "rumor_arcanum_samples", "text": "The Seekers are cataloguing creature changes. Whether every sample is authorized is another question.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 40)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_glass_collector', NULL, 'npc_glass_collector', 'greet', '[{"id": "greet", "text": "I''ll tell you right now — the good pieces aren''t for sale. But I have plenty of the rest.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Mina has spent years combing the Valley for pure Cradle Glass fragments. She sells the extras and keeps the finest for herself.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 41)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_cave_dax', NULL, 'npc_cave_spelunker', 'greet', '[{"id": "greet", "text": "What? Oh — yeah. Deep cave, lots of crystals, definitely haunted. Want specifics?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Dax descends into the Caverns daily and emerges with more data than anyone else alive. He''s partially deaf from the resonance hum.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 42)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_peak_watcher', NULL, 'npc_peak_watcher', 'greet', '[{"id": "greet", "text": "The readings spiked again. Something is building. I need a runner.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Watcher Vane monitors Shard energy peaks from the highest post in the region. She hasn''t slept a full night in two years.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 43)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_drax_main', NULL, 'npc_hegemony_commander', 'greet', '[{"id": "greet", "text": "You want a job? Prove you''re worth the oxygen first.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Commander Drax runs Bastion Core''s offensive operations with zero tolerance for failure or excuses. His record is unbroken because he breaks people first.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 44)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_ironhand', NULL, 'npc_blacksmith_ironhand', 'greet', '[{"id": "greet", "text": "Hegemony steel or something you''ve dragged in from the wasteland. Either way, I can work with it.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Ironhand earned his name when his right arm was replaced with a hydraulic exo-limb after a forge accident. Best thing that ever happened to his craft.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 45)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_rusty', NULL, 'npc_scrap_merchant', 'greet', '[{"id": "greet", "text": "Certified pre-owned! That''s my official position and I''m sticking to it.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Rusty runs the most chaotic stall in the Scrap Field, selling things he definitely did not assemble himself and definitely works.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 46)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_gorn_miner', NULL, 'npc_iron_miner', 'greet', '[{"id": "greet", "text": "Ores go down, iron comes up, credits change hands. That''s all there is.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_iron_worker", "action": ""}, {"text": "Any word from around here?", "next": "rumor_iron_quota", "action": ""}]}, {"id": "local", "text": "Gorn has mined the Ravine since before the Hegemony claimed it. He works for them now but misses the silence.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_iron_worker", "text": "The furnace quota went up again. The supports did not. If command wants another shift, they can come down and hear that beam sing.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_iron_quota", "text": "The Bastion raised the furnace quota and kept the same brace schedule.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 47)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_salvage_tink', NULL, 'npc_salvage_expert', 'greet', '[{"id": "greet", "text": "Every busted machine has one good thing left in it. I find it. You buy it. Works for everyone.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_iron_engineer", "action": ""}]}, {"id": "local", "text": "Tink specialises in extracting usable components from decommissioned Hegemony war machines. Her shop smells of coolant and ambition.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_iron_engineer", "text": "Don''t strike the old chassis after dusk. Not because it''s haunted; because the loose plate falls when the temperature drops.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 48)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_brigg_foreman', NULL, 'npc_assembly_foreman', 'greet', '[{"id": "greet", "text": "Clock''s running. Make it worth my time.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Foreman Brigg coordinates construction of Hegemony heavy units. He dispatches anyone who slows the line.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 49)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_vercelli_boss', NULL, 'npc_cartel_boss', 'greet', '[{"id": "greet", "text": "Welcome, welcome! Sit down. Have you eaten? Everyone eats at my table before we talk business.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Don Vercelli controls the Port Meridian dockside trade with a smile that never quite reaches his eyes. Everyone owes him something.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 50)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_salty_fisher', NULL, 'npc_wetland_fisher', 'greet', '[{"id": "greet", "text": "Careful out past the orange markers — something big has been circling.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_meridian_fisher", "action": ""}]}, {"id": "local", "text": "Old Salty has fished the Wetlands for fifty years and has opinions on everything. He shares them whether asked or not.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_meridian_fisher", "text": "The catch is fine. Getting it to Port Meridian costs more every week the jungle route stays uncertain.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 51)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_sly_smuggler', NULL, 'npc_shady_smuggler', 'greet', '[{"id": "greet", "text": "You''re either a customer or a problem. Which is it?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_meridian_smuggler", "action": ""}, {"text": "Any word from around here?", "next": "rumor_meridian_sketches", "action": ""}]}, {"id": "local", "text": "Sly operates out of a camp so well hidden that even Cartel enforcers can''t find it consistently. His prices reflect the inconvenience.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_meridian_smuggler", "text": "Someone is buying route sketches without asking who drew them. That is either a very careful buyer or a very careless one.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_meridian_sketches", "text": "A buyer is paying for route maps from every faction, not just Meridian.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 52)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_madam_z', NULL, 'npc_black_market_dealer', 'greet', '[{"id": "greet", "text": "Everything has a price. The question is what you''re willing to offer.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_cartel_dock", "action": ""}, {"text": "Any word from around here?", "next": "rumor_meridian_compact", "action": ""}]}, {"id": "local", "text": "Madam Z runs the most sophisticated black-market operation in three sectors. Her network spans factions. Her records are encrypted to oblivion.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_cartel_dock", "text": "The Cartel calls it a temporary fee. The dockhands call it a second rent. Both groups brought receipts.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_meridian_compact", "text": "A dock ledger mentions a Meridian Compact. Nobody agrees whether that was an office, a deal, or bad shorthand.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 53)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_kip_diver', NULL, 'npc_ruin_diver', 'greet', '[{"id": "greet", "text": "Got three contracts open and a window before the tide shifts. Short version: I need backup.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Kip free-dives the submerged Aethel ruins for Cartel clients, recovering artifacts that pre-date the current age. She has drowned three times and keeps going.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 54)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_sterling_exec', NULL, 'npc_omnicorp_executive', 'greet', '[{"id": "greet", "text": "Your efficiency rating is under evaluation. Perform accordingly.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Director Sterling manages OmniCorp field operations with corporate detachment. He sees people as human capital.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 55)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_tech404_side', NULL, 'npc_omnicorp_technician', 'greet', '[{"id": "greet", "text": "Task assigned. Completion expected. Questions are inefficient.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_omni_technician", "action": ""}, {"text": "Any word from around here?", "next": "rumor_omni_withdrawal", "action": ""}]}, {"id": "local", "text": "Tech Officer 404 handles everything from hardware diagnostics to covert extraction — and prefers not to explain why the two are related.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_omni_technician", "text": "The dashboard calls it an acceptable loss. The dashboard has never had to tell a family their shift is over.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_omni_withdrawal", "text": "The off-world board has asked for a new evacuation projection. They say it is routine.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 56)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_drone_7', NULL, 'npc_plateau_surveyor', 'greet', '[{"id": "greet", "text": "Surveyor Unit 7 online. Please state your resource-extraction inquiry.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_omni_survey", "action": ""}]}, {"id": "local", "text": "Surveyor Unit 7 is an autonomous OmniCorp drone with a remarkable personality subroutine that it has never been permitted to act on.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_omni_survey", "text": "Survey complete. The ground is stable enough for equipment. The phrase ''stable enough'' has been removed from the public projection.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 57)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_barrett_chief', NULL, 'npc_extraction_chief', 'greet', '[{"id": "greet", "text": "We''re behind quota. If you''re here to help, I''ll be grateful. If not, get clear of the machinery.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Chief Barrett has run OmniCorp extraction sites for eighteen years. She is equal parts miner, geologist, and combat veteran.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 58)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_warden_ai', NULL, 'npc_grid_security', 'greet', '[{"id": "greet", "text": "[WARDEN-7] Clearance verification required. Unauthorised access terminates this session.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Warden AI manages access to OmniCorp''s most sensitive mining operations. It has never once bent a rule.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 59)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_cross_engineer', NULL, 'npc_reactor_engineer', 'greet', '[{"id": "greet", "text": "I have exactly four minutes before the coolant flush. Talk fast.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Engineer Cross keeps the Skybridge Reactor from melting down on a daily basis. He has not taken a day off in three years.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 60)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_lyr_main', NULL, 'npc_high_priest', 'greet', '[{"id": "greet", "text": "The Shard has already seen this meeting. Come — what you seek to ask, it already knows.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "High Priestess Lyr is the spiritual and operational leader of the Children of the Shard. She speaks in certainties because she has heard the Shard speak.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 61)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mera_side', NULL, 'npc_acolyte_mera', 'greet', '[{"id": "greet", "text": "Lyr handles the visions. I handle the schedules. What can I help you with?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Acolyte Mera is the High Priestess'' deputy and does most of the work that keeping a religious order running actually requires.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 62)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_silas_forest', NULL, 'npc_forest_acolyte', 'greet', '[{"id": "greet", "text": "Walk slowly here. The Glowvines respond to rushed energy.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_shard_acolyte", "action": ""}]}, {"id": "local", "text": "Brother Silas tends the sacred Glowvine paths, pruning the luminescent vines and guiding pilgrims through the forest''s more disorienting sections.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_shard_acolyte", "text": "I hear a voice in the roots. Mera says grief can make any silence sound like an answer. I don''t know which of us is right.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 63)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_hermit', NULL, 'npc_swamp_hermit', 'greet', '[{"id": "greet", "text": "The swamp provides. Coin helps too. What are you after?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_shard_hermit", "action": ""}, {"text": "Any word from around here?", "next": "rumor_shard_purification", "action": ""}]}, {"id": "local", "text": "The Hermit lives alone at the swamp''s edge and claims the isolation is his by choice. His knowledge of Shard-touched flora is unmatched.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_shard_hermit", "text": "The water clears near the old stones, then clouds again downstream. A blessing would be simpler. This looks like a wound.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_shard_purification", "text": "Some elders want the Siphon destroyed. Others say the Shard never asked for blood.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 64)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_norn_keeper', NULL, 'npc_shrine_keeper', 'greet', '[{"id": "greet", "text": "Leave an offering, or don''t — the Shard judges intent, not tribute.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Keeper Norn has maintained the Fragment Shrine for three generations of her family. The shrine remembers what history has tried to erase.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 65)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_rell_guardian', NULL, 'npc_altar_guardian', 'greet', '[{"id": "greet", "text": "State your purpose at the Altar. Those who lie do not leave easily.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Guardian Rell is the last of the Altar''s sworn defenders. She speaks rarely and only when she has something worth saying.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 66)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_kaelen_main', NULL, 'npc_legion_general', 'greet', '[{"id": "greet", "text": "The Legion''s wars are never truly over — they only pause. Come, there is work.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "General Kaelen is the Starforged Legion''s most decorated commander and the fortress'' namesake ancestor''s descendant. Every scar has a story.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 67)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_korg_side', NULL, 'npc_drill_sergeant_korg', 'greet', '[{"id": "greet", "text": "WHAT ARE YOU DOING STANDING THERE. Move, recruit!", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Sergeant Korg has broken and rebuilt more recruits than any drill sergeant in Legion history. He considers this a compliment.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 68)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_jace_scout', NULL, 'npc_dune_scout', 'greet', '[{"id": "greet", "text": "Sandstorm coming from the west in three hours. You''ll want to be clear of the flats.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Scout Jace runs the farthest perimeter patrols alone and prefers it that way. She knows the dunes better than the sand knows itself.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 69)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_rex_survivor', NULL, 'npc_badland_survivor', 'greet', '[{"id": "greet", "text": "Prices are high because everything out here costs blood to move. Pay or move on.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_legion_survivor", "action": ""}, {"text": "Any word from around here?", "next": "rumor_legion_settlement", "action": ""}]}, {"id": "local", "text": "Rex survived a collapse in the Mesa Warpath and set up the only trading post between the Badlands and the Fortress. He charges accordingly.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_legion_survivor", "text": "Back home, a roof meant you had stopped moving. Here, the young ones argue over which wall gets a window. I let them.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_legion_settlement", "text": "The Legion is planning permanent water storage beside its new housing blocks.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 70)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_gorok_vet', NULL, 'npc_warpath_veteran', 'greet', '[{"id": "greet", "text": "Read the names on the wall before you take any contract from me. All of them.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_legion_veteran", "action": ""}]}, {"id": "local", "text": "Veteran Gorok fought in the Mesa Warpath campaigns and returned to guard the memorial. He gives contracts to those who understand what they''re walking into.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_legion_veteran", "text": "We used to name a formation after its commander. Now we name it after the people who made it back. Better record.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 71)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_dan_smithy', NULL, 'npc_lost_blacksmith', 'greet', '[{"id": "greet", "text": "Took the long route to find me. Good — means you actually need something forged right.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Smithy Dan set up a forge in the middle of nowhere after being blacklisted by every guild. His work is better than his manners.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 72)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_vance_medic', NULL, 'npc_battlefield_medic', 'greet', '[{"id": "greet", "text": "Wound first, introductions second. Sit down.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Medic Vance works the neutral zone, patching up anyone from any faction. He says he has no politics. Everyone believes him.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 73)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_traveling_trader', NULL, 'npc_wandering_trader', 'greet', '[{"id": "greet", "text": "The rare finds the rare. You''ve found me — so you must be looking for something unusual.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The Traveling Merchant has no fixed location and appears at crossroads when least expected. Some say they''re the same person across decades; others say they''re a fleet.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 74)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_jax_scout', NULL, 'npc_reckless_scout', 'greet', '[{"id": "greet", "text": "I''ve been to the dead zones. Twice. Still alive, so clearly I''m doing something right.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Scout Jax goes where no briefing covers and comes back with information no intel team was willing to get.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 75)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_tark_frontline', NULL, 'npc_frontline_commander', 'greet', '[{"id": "greet", "text": "Nobody is cooperating. Again. Are you here to help or to make things worse?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Commander Tark leads a multi-faction peacekeeping force that nobody actually obeys. He keeps trying anyway.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 76)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_void_walker', NULL, 'npc_void_walker', 'greet', '[{"id": "greet", "text": "You see me. Most do not. That means the Void has noticed you already.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The Nameless Walker exists between states — half in this world, half in the Void. They offer guidance but no comfort.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 77)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_prophet', NULL, 'npc_doomsayer', 'greet', '[{"id": "greet", "text": "I see you''ve come to hear something terrible. I''ll oblige.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The Prophet claims to have seen how every faction ends. His predictions are specific, detailed, and have a troubling accuracy rate.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 78)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_aris_core', NULL, 'npc_core_technician', 'greet', '[{"id": "greet", "text": "The Core is stable. For now. I need someone who can run interference on the eastern conduit.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Tech Lead Aris maintains the most dangerous energy extraction operation in the Concordium — a job that has taken three predecessors.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 79)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_master_kael', NULL, 'npc_master_kael', 'greet', '[{"id": "greet", "text": "Most people who come here aren''t ready. Convince me you''re different.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Master Kael is the only living crafter authorised to work with Prima Materia. He accepts commissions once per season, if he finds the requester worthy.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 80)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_xylar_smith', NULL, 'npc_abyssal_smith', 'greet', '[{"id": "greet", "text": "Void-forged items remember their makers. I only work for those who will be remembered in turn.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Xylar the Abyssal forges weapons using Void-touched metal that no standard smith will touch. The products are extraordinary. So is the risk.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 81)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_ancient_ghost', NULL, 'npc_ancient_ghost', 'greet', '[{"id": "greet", "text": "You stand in what was once a great city. I am what remembers it.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The Echo of Aethelgard is a residual consciousness from before the Fracture, preserved in a crystalline matrix. Its memories are the only record of the old world.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 82)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_resonance_entity', NULL, 'npc_echo_entity', 'greet', '[{"id": "greet", "text": "... (the air crackles with recognition)", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The Resonance is an entity formed from accumulated Aethel energy, neither fully conscious nor fully absent. It responds to genuine questions.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 83)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_custodian_ai', NULL, 'npc_custodian_ai', 'greet', '[{"id": "greet", "text": "[CUSTODIAN PRIME] Authenticated connection established. What resource allocation do you require?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_custodian_ai", "action": ""}, {"text": "Any word from around here?", "next": "rumor_custodian_threshold", "action": ""}]}, {"id": "local", "text": "Orbital Custodian Prime is the administrative intelligence of the Custodian orbital station. Neutral in all factional conflicts; ruthless in operational efficiency.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_custodian_ai", "text": "Observation remains below intervention threshold. The threshold is a policy choice, not a measurement of suffering.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_custodian_threshold", "text": "The Custodians are watching Xylos but have not authorized intervention.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 84)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_ross_main', NULL, 'npc_commander_ross', 'greet', '[{"id": "greet", "text": "I have three missions that need immediate assignment. Priorities, in order.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Commander Ross leads the Concordium''s high-risk operations in the fractured core regions. She gives orders calmly and expects them followed precisely.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 85)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_elara_main', NULL, 'npc_strategist_elara', 'greet', '[{"id": "greet", "text": "The Storm Belt follows patterns. I know them. I''ll tell you where to be.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Strategist Elara analyses the Storm Belt anomalies and translates raw data into actionable field assignments.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 86)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_vin_main', NULL, 'npc_researcher_vin', 'greet', '[{"id": "greet", "text": "Yes, yes — come in. Just don''t touch the crystal array. Or that. Or — actually, touch nothing.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Researcher Vin is deep in a classified study of the Cavern''s resonance peaks and needs reliable field agents who ask fewer questions.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 87)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_soren_main', NULL, 'npc_admiral_soren', 'greet', '[{"id": "greet", "text": "From orbit, everything looks small. From the ground, nothing feels small. I need agents who understand both.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Admiral Soren commands the Custodian orbital fleet and coordinates missions that require both orbital and ground assets.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 88)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_exchange_crossroad', NULL, 'npc_crossroad_exchange', 'greet', '[{"id": "greet", "text": "The Credent is universal. Exchange your faction currency here — equal rates for all.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "An Aegis Monetary Authority representative facilitating faction currency exchange to CRD.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 89)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_envoy_greet', NULL, 'npc_crossroad_envoy', 'greet', '[{"id": "greet", "text": "Greetings, wanderer. I am Envoy Kalen, servant of the Custodians. How may the galaxy assist you today?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A Galactic Custodian envoy station. Provides lore, news, and direction to travelers.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 90)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_exchange_bazaar', NULL, 'npc_bazaar_exchange', 'greet', '[{"id": "greet", "text": "Large volume exchange? I handle the accounts that shape planetary economies.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A senior AMA auditor overseeing large-volume currency exchange operations.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 91)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_exchange_orbital', NULL, 'npc_orbital_exchange', 'greet', '[{"id": "greet", "text": "The Credent is the pulse of galactic economy. Exchange wisely — fortunes rise and fall in moments.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "The AMA Chancellor overseeing all Xylos currency operations from orbit.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 92)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_elara_main', NULL, 'NPC_NEXUS_MERCHANT_ELARA', 'greet', '[{"id": "greet", "text": "Welcome to Elara''s Supplies. I don''t care what flag you fly — just don''t cause trouble in my stall. What do you need?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A former Meridian Cartel logistics officer who left after witnessing the human cost of trade wars. She now runs a supply stall in the Nexus, selling to anyone with enough CRD and a civil manner. Elara is known for her encyclopedic knowledge of contraband detection and her distaste for faction politics.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 93)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_grath_main', NULL, 'NPC_NEXUS_MERCHANT_GRATH', 'greet', '[{"id": "greet", "text": "You look like you''ve been through a meat grinder. Or you''re about to be. Either way, I''ve got what you need. In CRD.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A retired Iron Hegemony sergeant with a cybernetic left arm and a grudge against every faction equally. He sells weapons, repair kits, and battle supplies. He claims to have fought in seven wars for five different factions before deciding none of them were worth dying for.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 94)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_tessara_main', NULL, 'NPC_NEXUS_INNKEEPER_TESSARA', 'greet', '[{"id": "greet", "text": "Ah, a wanderer with tired eyes. Come, rest your burdens. My inn welcomes all who arrive in peace. Your body will thank you in the morning.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A former Arcanum Seekers adept who left the Order after discovering that true peace of mind doesn''t come from forbidden knowledge, but from a warm meal and a good night''s sleep. She operates the finest inn in the Nexus, famous for the restorative quality of her brews and her uncanny ability to read a person''s soul.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 95)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_vulkan_main', NULL, 'NPC_NEXUS_BLACKSMITH_VULKAN', 'greet', '[{"id": "greet", "text": "Materials on the bench, CRD in the slot. I don''t chit-chat while I work, but I''ll say this — what comes off my forge won''t disappoint you.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Vulkan was once a legendary weapons master for the Starforged Legion before a catastrophic forge accident left him without faction allegiance or half his hearing. He rebuilt his workshop in the Nexus and now crafts for anyone. He has a unique skill: he can work with materials from ANY faction, which no capital blacksmith is willing to do.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 96)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_arbiter_main', NULL, 'NPC_NEXUS_QUESTGIVER_ARBITER', 'greet', '[{"id": "greet", "text": "You''ve arrived at a time of delicate balance, traveler. The Custodians always have need of capable individuals who operate above faction lines. Are you such a person?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A Galactic Custodians arbiter assigned to the Nexus to monitor inter-faction tensions and dispense justice under the Charter. Lorn is a calm, methodical individual who has seen enough war to know that every conflict has preventable roots. He offers missions that promote stability, investigation, and cross-faction cooperation.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 97)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_commander_main', NULL, 'NPC_NEXUS_QUESTGIVER_COMMANDER', 'greet', '[{"id": "greet", "text": "I don''t have time for pleasantries. You either have what it takes or you don''t. The Custodians have a mission. The question is: are you the right operative?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A decorated Pact-Keeper Frigate commander who now coordinates special operations from the Nexus. She recruits independent operators for missions too sensitive for the official Sentinel Fleet — retrieving forbidden tech, eliminating rogue AI nodes, or investigating threats to Pax Galactica stability. She is direct, efficient, and has no patience for excuses.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 98)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_ama7_main', NULL, 'NPC_NEXUS_BANKER_AMA7', 'greet', '[{"id": "greet", "text": "Welcome to the Aegis Monetary Authority exchange terminal. Current exchange rates are live. I advise reviewing the economic factors panel before committing to a transaction. The Credent does not forgive market ignorance.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_ama_ledger", "action": ""}, {"text": "Any word from around here?", "next": "rumor_counterfeit_credent", "action": ""}]}, {"id": "local", "text": "NEXON AMA-7 is the primary exchange terminal for the Aegis Monetary Authority in Pax Nexus. It is a non-conscious but highly intelligent administrative AI that manages real-time currency exchange between all faction currencies and the Credent (CRD). It speaks in precise economic terminology and has a subtle personality quirk: it quotes historical economic disasters as a warning when exchange rates are particularly volatile.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_ama_ledger", "text": "Your exchange cleared at the posted rate. The fee is visible in the ledger; the reason for it should be too.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}, {"id": "rumor_counterfeit_credent", "text": "The AMA flagged forged CRD samples near the mining grid. A sample is not proof of a coordinated attack.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 99)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_echo01_main', NULL, 'NPC_NEXUS_GUIDE_ECHO01', 'greet', '[{"id": "greet", "text": "Oh! A new arrival! Welcome to Pax Nexus — the only place in the galaxy where a Concordium soldier and a Shard mystic can share a meal without incident. Usually. I''m ECHO-01. I know everything. Well, almost everything. Ask me anything!", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "ECHO-01 is a holographic guide entity created by the Custodians to help new arrivals understand the rules of Pax Nexus and the broader world of Xylos. It has developed a curious sense of humor and philosophical outlook despite being a guidance program. ECHO-01 secretly enjoys meeting travelers from different factions and comparing their perspectives.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 100)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_chronicler_main', NULL, 'NPC_NEXUS_INFO_CHRONICLER', 'greet', '[{"id": "greet", "text": "Ah. Another thread arrives to be woven into the tapestry. I have recorded ten thousand such arrivals. Tell me, traveler — which version of yourself do you wish to become? I have seen all of them.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}, {"text": "How are the locals holding up?", "next": "amb_neutral_refugee", "action": ""}]}, {"id": "local", "text": "The Chronicler is an ancient being of unknown species who has been recording galactic history for longer than any faction has existed. It/they speak in a calm, layered voice that seems to come from multiple directions at once. The Chronicler offers history, lore, and cryptic hints about world events. Occasionally, it whispers of things that have not happened yet.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}, {"id": "amb_neutral_refugee", "text": "A family at the south convoy desk is still waiting for an arrival time. The board keeps giving them a percentage.", "options": [{"text": "I''ll remember that.", "next": "greet", "action": ""}]}]'::jsonb, 'dialog_tree_master.json', 101)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_vael_main', NULL, 'NPC_NEXUS_DIPLOMAT_VAEL', 'greet', '[{"id": "greet", "text": "Peace is not the absence of conflict, traveler. It is the choice to act differently. I have a few... diplomatic errands that require someone who can operate beyond faction lines. Interested?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Ambassador Vael is the Custodians'' highest diplomatic representative in Pax Nexus. They navigate the razor-thin line between faction politics with grace, and occasionally task trusted operatives with missions that shape inter-faction relations. Completing Vael''s quests can shift faction war status, unlock peace treaties, or trigger major world events.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 102)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_sable_main', NULL, 'NPC_NEXUS_TRADER_SABLE', 'greet', '[{"id": "greet", "text": "Looking for something, friend? I have a feeling I know what it is. That''s my gift. Well, one of them. Everything here is perfectly legal, I assure you. The Arbiter checked last Tuesday.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Sable operates in the legal grey zone. Their wares are technically not contraband — the Custodians have checked, repeatedly — but they always seem to have exactly what you didn''t know you needed. Rare materials, faction-specific items that shouldn''t be sold outside their territory, and items that appear in the ledger as ''miscellaneous recoveries.'' Sable never asks where things came from.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 103)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_mira_main', NULL, 'NPC_NEXUS_HEALER_MIRA', 'greet', '[{"id": "greet", "text": "You''ve been hurt. I can see it — not just in your body. Come. The Infirmary is open to all. No politics, no faction marks, no judgments. Just healing.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Mira was once a battlefield medic for the Children of the Shard before her faith in their methods was shattered after a brutal campaign. She left the Shard with their medical knowledge intact and a vow to heal without discrimination. The Nexus Infirmary she runs is open to all factions, all hours. She is gentle, precise, and deeply empathetic.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 104)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_ghost_main', NULL, 'NPC_NEXUS_QUESTGIVER_SMUGGLER', 'greet', '[{"id": "greet", "text": "Ah, a fresh face. And by the look of you, a capable one. I have work that pays well, asks no inconvenient questions, and officially never happened. Sound like your kind of business?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Ghost is an infamous freelancer who sells information and contracts to anyone who can pay. He has no faction loyalty but seems to know every faction''s secrets. His quests are morally ambiguous but always lucrative. The Arbiter watches him closely, but Ghost has never technically broken the Charter. He lives in the technical spaces between the rules.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 105)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_nexus_axis_main', NULL, 'NPC_NEXUS_TRAINER_AXIS', 'greet', '[{"id": "greet", "text": "AXIS Class Advancement Terminal online. I support all class trees from all seven factions, including cross-faction hybrid builds unavailable at capital trainers. Standard fee in CRD applies. Shall we begin assessment?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "AXIS is a holographic training AI that can facilitate class advancement for any faction''s character build. Unlike capital-based trainers who specialize only in their faction''s classes, AXIS can handle cross-faction hybrid advancement paths. This makes it the most sought-after trainer in Xylos, and the most expensive.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 106)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_custodian_banker', NULL, 'npc_ledger_warden_nexus_core', 'greet', '[{"id": "greet", "text": "Authorization confirmed. Vault and exchange services are available. What do you require, citizen?", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "A Galactic Custodian field agent assigned to the financial sovereignty infrastructure of Nexus Core. Processes vault deposits, withdrawals, and AMA-regulated currency exchange under Pax Nexus protocol.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 107)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_lirien_vale_main', NULL, 'npc_commander_vale', 'greet', '[{"id": "greet", "text": "The route report first. Then tell me what you saw.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Field commander responsible for Concordium operations across the Gardens and Cradle. She weighs operational success against the people who pay for it.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 108)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_harkon_steele_main', NULL, 'npc_warlord_steele', 'greet', '[{"id": "greet", "text": "State your readiness. I have a line to hold.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Hegemony warlord overseeing field operations and the recovery of strategic industrial ground.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 109)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_don_vercelli_mox_main', NULL, 'npc_don_mox', 'greet', '[{"id": "greet", "text": "Sit. We can decide whether this is business after we hear the whole story.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Cartel leader whose influence rests on routes, favors, and information as much as cargo.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 110)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_elder_malakor_main', NULL, 'npc_elder_malakor', 'greet', '[{"id": "greet", "text": "Listen before you answer. The forest has been trying to tell us something.", "options": [{"text": "What''s happening around here?", "next": "local", "action": ""}, {"text": "I''ll leave you to it.", "next": "exit", "action": "exit"}]}, {"id": "local", "text": "Senior voice among the Children of the Shard. His interpretation of the Shard is a religious belief, not established fact.", "options": [{"text": "Thanks for the word.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The conversation pauses.", "options": []}]'::jsonb, 'dialog_tree_master.json', 111)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mystery_unlisted_greet', NULL, 'npc_mystery_edda_fen', 'greet', '[{"id": "greet", "text": "Names first. Numbers can wait. Two chairs face an empty doorway. Only the smaller chair has fresh repairs. Household numbers continue across a wall that modern surveys label vacant.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "The small chair has fresh binding; the large one has weathered dust.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Edda needs an independent field witness because official corrections require evidence and she refuses to publish refugees'' addresses.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 112)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_npc_mystery_unlisted_clue_1', NULL, 'npc_mystery_unlisted_clue_1', 'greet', '[{"id": "greet", "text": "Two chairs face an empty doorway. Only the smaller chair has fresh repairs. Household numbers continue across a wall that modern surveys label vacant.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "The lower numeral is cut into stone; the upper numeral is painted.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "Two chairs face an empty doorway. Only the smaller chair has fresh repairs. Household numbers continue across a wall that modern surveys label vacant.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 113)
