insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_npc_mystery_unlisted_clue_2', NULL, 'npc_mystery_unlisted_clue_2', 'greet', '[{"id": "greet", "text": "The lower series skips occupied doors but follows conduit junctions.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "The lower series skips occupied doors but follows conduit junctions.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "Two chairs face an empty doorway. Only the smaller chair has fresh repairs. Household numbers continue across a wall that modern surveys label vacant.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 114)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mystery_muster_greet', NULL, 'npc_mystery_tovan_rell', 'greet', '[{"id": "greet", "text": "Hear the gap. Metal tells on itself. A muster bell hangs over boots facing away from the parade line. A second rope leads into a workshop, not a command tower.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "The tally labels the fourth beat evacuate.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Tovan repairs signal bells for civilians who worked beside Iron and Legion crews. He needs an outsider to compare records neither employer will share with him.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 115)
