insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mystery_zero_greet', NULL, 'npc_mystery_sella_quinn', 'greet', '[{"id": "greet", "text": "Read the unit before you buy the number. A berth marked zero contains a crate with an inward-facing shipping stencil. A polished scale shows the same value even with no cargo.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "The cargo column is blank, not marked lost.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Sella needs a field examiner outside her former OmniCorp employer and Meridian creditors to distinguish damaged cargo from a manipulated claim.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 118)
